using System;using System.IO;using System.Text;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Windows.Forms;
public static class PriorityExplanation {
 public static string DescribeResearchAssumptions(Dictionary<string,object> candidate){var b=new StringBuilder("Порядок сравнения: заголовок / тип / ID; это не бизнес-ранг.");b.AppendLine();b.AppendLine("Покупатель — гипотеза; клиент владельца не подтверждён. Личные связи, trucking-контакты и аудитория владельца не предполагаются и не дают преимуществ в глобальном сравнении.");foreach(string key in new[]{"market_score","sales","profit"}){object value;candidate.TryGetValue(key,out value);b.AppendLine(key+": "+(value==null?"НЕИЗВЕСТНО (не ноль)":Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture)+" — сохранённое неподтверждённое значение, не доказанный результат"));}b.AppendLine("Выручка — поступления от продаж; денежный вклад — выручка минус указанные денежные затраты. Это не чистая прибыль: труд владельца, налоги и прочие неуказанные расходы остаются неизвестными. Цена чужого продукта и вопрос в сообществе не доказывают продажи или прибыль нашего продукта.");return b.ToString();}
 static readonly string[] Fields={"Name","Model","Buyer","Thesis","Status","Auto","Bal","Growth","Revenue","Contribution","Startup","Automation","OwnerHours","LaunchDays"};
 static object Value(object row,string name){var field=row.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(field==null)throw new InvalidDataException("Unknown legacy score field: "+name);return field.GetValue(row);}
 public static string Describe(Form form,string appRoot){
  var flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=form.GetType();var data=(IEnumerable)type.GetField("data",flags).GetValue(form);var lens=type.GetField("lens",flags).GetValue(form) as ComboBox;string score="Bal";string path=Path.Combine(appRoot,"reveng_local_data.tsv");string[] lines=new string[0];string fileError="";try{if(new FileInfo(path).Length>8388608)throw new InvalidDataException("TSV exceeds8MiB");lines=File.ReadAllLines(path,Encoding.UTF8);}catch(Exception ex){fileError=ex.Message;}
  var b=new StringBuilder("Основания старого порядка Opportunities\r\n\r\n");
  b.AppendLine("Активного бизнес-ранга нет. Архив отображает исходный порядок строк TSV. Auto/Bal/Growth — только сохранённые сценарные числа, а не правило текущего порядка; переключатель архивного рейтинга отключён.");
  b.AppendLine("Это объяснение прежней сортировки по сохранённым числам. В основном архиве теперь используется порядок записей, а Compare/Blueprint не выбирают лучшую идею по этим числам. Кто и по какой методике присвоил каждый балл, неизвестно. Источник чисел — локальная строка TSV, если она совпадает со значениями в памяти; ссылка на исходное свидетельство и расчёт отсутствуют. Балл не является вероятностью успеха, проверкой спроса или рекомендацией инвестировать.");
  b.AppendLine("Auto — отдельный старый балл; Automation — отдельный сохранённый процент. Выручка, вклад, стартовые затраты, часы владельца и дни запуска — сохранённые сценарные числа с неизвестным обоснованием, а не результаты измерений. Покупатель и thesis — гипотезы. Контакты, опыт и связи пользователя из них не выводятся.");
  b.AppendLine("Исследовательские модельные и ранние карточки — отдельный список без установленной связи с этими TSV-сценариями. Проверенный рыночный балл для них не вычисляется. В Research порядок карточек не означает приоритет по доходности; смотрите исходный текст, ручной разбор, неизвестное и условный следующий шаг.");
  if(fileError!="")b.AppendLine("TSV не прочитан; происхождение значений не подтверждено: "+fileError);else b.AppendLine("TSV SHA256: "+LocalResearchController.Hash(path));
  b.AppendLine("Фактический порядок архива — исходный порядок строк TSV, не Auto/Bal/Growth. Отключённый переключатель не управляет порядком. Revenue — выручка, Contribution — денежный вклад; ни одно из них не является чистой прибылью. Прибыль, личные контакты владельца и подтверждённый спрос неизвестны; эти числа — неподтверждённые сценарии.");int rowIndex=0;foreach(object row in data){var values=Fields.Select(f=>Convert.ToString(Value(row,f),System.Globalization.CultureInfo.InvariantCulture)).ToArray();bool match=false;if(rowIndex<lines.Length)try{var cells=lines[rowIndex].Split('\t');match=cells.Length==Fields.Length&&Fields.Select((f,i)=>i<5?Encoding.UTF8.GetString(Convert.FromBase64String(cells[i])):cells[i]).SequenceEqual(values);}catch{}b.AppendLine().AppendLine(values[0]);b.AppendLine("Модель (сохранено): "+values[1]).AppendLine("Покупатель (сценарное предположение, не подтверждённый клиент): "+values[2]).AppendLine("Тезис (сохранённая гипотеза): "+values[3]).AppendLine("Метка состояния сценария: "+values[4]+"; это не автоматическое подтверждение спроса/победителя.");b.AppendLine("Выбранный балл "+score+" = "+Value(row,score)+"; основание: "+(match?"reveng_local_data.tsv, строка "+(rowIndex+1)+", столбец "+(Array.IndexOf(Fields,score)+1):"текущие значения в памяти; совпадение со строкой TSV не подтверждено, возможны незаписанные изменения")+". Связанный источник/формула присвоения: неизвестны.");for(int i=5;i<Fields.Length;i++)b.AppendLine(Fields[i]+" = "+values[i]+" | "+(match?"TSV строка "+(rowIndex+1)+", столбец "+(i+1):"значение в памяти")+" | исходное обоснование: неизвестно");rowIndex++;}
  b.AppendLine().AppendLine("Для решения не хватает: повторяемости проблемы с точными источниками и независимостью авторов; реального плательщика и признака оплаты; проверки существующих решений для конкретной задачи; измеримых затрат и условий использования; результата безопасной проверки с критериями успеха/опровержения. Числа выше эти пробелы не закрывают. Следующий шаг выбирается по конкретному источнику, а его выполнение требует соответствующего разрешения.");return b.ToString();
 }
}
